// js/smoke_mode.js
import { setDataStatus, setDataError } from "./data_status.js";

// Shared AirNow snapshot generated by the scheduled job. Visitors never call the API.
const SMOKE_URL = new URL("public/data/smoke_ca_latest.geojson", document.baseURI).toString();

function getAqiColor(aqi) {
  if (aqi <= 50)  return "#00e400";
  if (aqi <= 100) return "#ffff00";
  if (aqi <= 150) return "#ff7e00";
  if (aqi <= 200) return "#ff0000";
  if (aqi <= 300) return "#8f3f97";
  return "#7e0023";
}

const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, char => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
})[char]);

// ======== 内部状态 ========
let smokeLayerGroup = null;
let infoControl = null;
let legendControl = null;
let refreshTimer = null;

// ======== 渲染 ========
function makeMarker(feature, latlng) {
  const aqi = Number(feature?.properties?.aqi);
  const color = Number.isFinite(aqi) ? getAqiColor(aqi) : "#999";
  return L.circleMarker(latlng, {
    radius: 5,
    color,
    fillColor: color,
    fillOpacity: 0.8,
    weight: 1,
  });
}

function bindPopup(feature, layer) {
  const p = feature.properties || {};
  const last = p.observed_at_utc ? new Date(p.observed_at_utc).toLocaleString() : "n/a";
  const pmLine = p.pm2_5 == null ? "" : `<div>Raw PM2.5: <b>${escapeHTML(p.pm2_5)}</b> μg/m³</div>`;
  const html = `
    <div style="min-width:220px">
      <div><b>${escapeHTML(p.site_name || "AirNow monitoring site")}</b></div>
      <div>PM2.5 AQI: <b>${escapeHTML(p.aqi ?? "n/a")}</b></div>
      ${pmLine}
      <div>Observed: ${escapeHTML(last)}</div>
      <small>Preliminary EPA AirNow observation</small>
    </div>`;
  layer.bindPopup(html);
}

function drawSmokeLayer(map, features) {
  const nextLayer = L.geoJSON(
    { type: "FeatureCollection", features: features || [] },
    {
      pointToLayer: makeMarker,
      onEachFeature: bindPopup,
    }
  ).addTo(map);
  if (smokeLayerGroup) map.removeLayer(smokeLayerGroup);
  smokeLayerGroup = nextLayer;
}

// ======== 控件（可选） ========
function addLegend(map) {
  if (legendControl) map.removeControl(legendControl);
  legendControl = L.control({ position: "bottomright" });
  legendControl.onAdd = function () {
    const div = L.DomUtil.create("div", "info legend");
    const stops = [
      [0, 50, "#00e400", "0–50"],
      [51, 100, "#ffff00", "51–100"],
      [101, 150, "#ff7e00", "101–150"],
      [151, 200, "#ff0000", "151–200"],
      [201, 300, "#8f3f97", "201–300"],
      [301, 500, "#7e0023", "301–500"],
    ];
    div.innerHTML = `<b>AQI (PM2.5)</b><br>` + stops.map(s =>
      `<i style="background:${s[2]};width:12px;height:12px;display:inline-block;margin-right:6px;"></i>${s[3]}`
    ).join("<br>");
    return div;
  };
  legendControl.addTo(map);
}

function addInfo(map) {
  if (infoControl) map.removeControl(infoControl);
  infoControl = L.control({ position: "topright" });
  infoControl.onAdd = function () {
    const div = L.DomUtil.create("div", "info");
    div.style.padding = "6px 8px";
    div.style.background = "white";
    div.style.borderRadius = "6px";
    div.style.boxShadow = "0 1px 4px rgba(0,0,0,0.2)";
    div.innerHTML = `<b>Air quality (EPA AirNow)</b><div id="smoke-meta" style="font-size:12px;color:#666">Loading…</div>`;
    return div;
  };
  infoControl.addTo(map);
}

function updateInfo(meta) {
  const el = document.getElementById("smoke-meta");
  if (!el) return;
  const observed = meta?.observed ?? null;
  const fetched = meta?.fetched ?? null;
  el.textContent = observed
    ? `Observed: ${new Date(observed).toLocaleString()} · Fetched: ${new Date(fetched).toLocaleString()} · Preliminary`
    : "Observation time unavailable";
}

// ======== 对外 API ========

/**
 * 初始化：加控件 + 首次取数 +（可选）定时刷新
 */
export async function initSmokeMode(map, { refreshSec = 0 } = {}) {
  addInfo(map);
  addLegend(map);

  try { await refreshSmokeMode(map); } catch (err) { console.warn("smoke snapshot unavailable:", err); }

  if (refreshTimer) clearInterval(refreshTimer);
  if (refreshSec > 0) {
    refreshTimer = setInterval(() => {
      refreshSmokeMode(map)
        .catch(err => console.error("smoke refresh error:", err));
    }, refreshSec * 1000);
  }

  return smokeLayerGroup;
}

/**
 * 手动刷新（被 init 或按钮调用）
 */
export async function refreshSmokeMode(map) {
  try {
    const resp = await fetch(SMOKE_URL, { cache: "no-store" });
    if (!resp.ok) throw new Error(`Smoke snapshot HTTP ${resp.status}`);
    const fc = await resp.json();
    if (fc.source !== "EPA AirNow" || !Array.isArray(fc.features) || !fc.source_updated_at_utc) {
      throw new Error("Invalid AirNow snapshot");
    }
    drawSmokeLayer(map, fc.features);
    setDataStatus("Smoke", fc.source_updated_at_utc, 3 * 60 * 60 * 1000);
    updateInfo({ observed: fc.source_updated_at_utc, fetched: fc.fetched_at_utc });
  } catch (error) {
    setDataError("Smoke");
    throw error;
  }
}

/**
 * 关闭：移除图层与控件、清掉定时器
 */
export function removeSmokeMode(map) {
  if (refreshTimer) { clearInterval(refreshTimer); refreshTimer = null; }
  if (smokeLayerGroup) { map.removeLayer(smokeLayerGroup); smokeLayerGroup = null; }
  if (infoControl) { map.removeControl(infoControl); infoControl = null; }
  if (legendControl) { map.removeControl(legendControl); legendControl = null; }
}
